import type { MessageContent } from "@loomcast/contracts";
import { index, jsonb, pgTable, uniqueIndex, uuid } from "drizzle-orm/pg-core";
import { createdAt, uuidPrimaryKey } from "./columns";
import { conversations } from "./conversations";
import { messageRole } from "./enums";
import { jobs } from "./jobs";
import { users } from "./users";

/**
 * Messages of a conversation. `clientMessageId` is generated by the web app, so a double-send hits
 * the unique index instead of creating a second message. Rows without one never conflict.
 */
export const messages = pgTable(
  "messages",
  {
    id: uuidPrimaryKey(),
    conversationId: uuid("conversation_id")
      .notNull()
      .references(() => conversations.id, { onDelete: "cascade" }),
    role: messageRole("role").notNull(),
    authorUserId: uuid("author_user_id").references(() => users.id),
    jobId: uuid("job_id").references(() => jobs.id, { onDelete: "set null" }),
    clientMessageId: uuid("client_message_id"),
    content: jsonb("content").$type<MessageContent>().notNull(),
    createdAt: createdAt(),
  },
  (t) => [
    uniqueIndex("messages_conversation_id_client_message_id_uq").on(
      t.conversationId,
      t.clientMessageId,
    ),
    index("messages_conversation_id_created_at_idx").on(t.conversationId, t.createdAt),
  ],
);

export type MessageRow = typeof messages.$inferSelect;
export type NewMessageRow = typeof messages.$inferInsert;
